    submitterAccessService,
    accountDeletionService,
    adminService,
    ...(weatherService !== undefined ? { weatherService } : {}),
    ...(fixtureWeatherService !== undefined ? { fixtureWeatherService } : {}),
    ...(batchService !== undefined ? { batchService } : {}),
  });
}

