import type { PublicEvent } from '@sport-analytics/contracts';
import { describe, expect, test, vi } from 'vitest';

import type { QueryExecutor } from '../../src/database';
import { createPublicEventRepository } from '../../src/modules/events/event.repository';

function event(eventId: string, sequenceNumber: number): PublicEvent {
  return {
    eventId,
    fixtureId: '100',
    inningsId: '200',
    inningsOrdinal: 0,
    sequenceNumber,
    overNumber: 4,
    positionInOver: sequenceNumber - 1,
    ballNumber: `4.${sequenceNumber}`,
    battingCompetitorId: '20',
    bowlingCompetitorId: '21',
    strikerParticipantId: '30',
    nonStrikerParticipantId: '31',
    bowlerParticipantId: '32',
    runs: {
      offBat: 0,
      extras: 0,
      total: 0,
      nonBoundary: false,
    },
    extras: {
      wides: null,
      noBalls: null,
      byes: null,
      legByes: null,
      penalty: null,
    },
    wickets: [],
  };
}

describe('public event repository', () => {
  test('selects accepted current revisions in fixture order with whitelisted filters', async () => {
    const query = vi.fn().mockResolvedValue({
      rows: [event('501', 2), event('502', 3), event('503', 4)],
      rowCount: 3,
      command: 'SELECT',
      oid: 0,
      fields: [],
    });
    const repository = createPublicEventRepository({ query } as unknown as QueryExecutor);

    const page = await repository.listAcceptedFixtureEvents({
      fixtureId: '100',
      inningsId: '200',
      competitorId: '20',
      participantId: '30',
      overNumber: 4,
      wicketKind: 'caught',
      after: {
        inningsOrdinal: 0,
        sequenceNumber: 1,
        eventId: '500',
      },
      limit: 2,
    });

    expect(page.records.map((record) => record.eventId)).toEqual(['501', '502']);
    expect(page.hasMore).toBe(true);

    const sql = String(query.mock.calls[0]?.[0]);
    expect(sql).toContain("source_submission.status = 'accepted'");
    expect(sql).toContain(
      'DISTINCT ON (delivery.innings_id, delivery.over_number, delivery.position_in_over)',
    );
    expect(sql).toContain('i.batting_team_id = $3::bigint');
    expect(sql).toContain('participant_wicket.player_out_id = $4::bigint');
    expect(sql).toContain('d.over_number = $5::smallint');
    expect(sql).toContain('filtered_wicket.kind = $6::text');
    expect(sql).toContain('ORDER BY i.ordinal ASC, d.innings_sequence ASC, d.delivery_id ASC');
    expect(sql).not.toContain('submitted_by AS');
    expect(sql).not.toContain('recorded_at AS');
    expect(query.mock.calls[0]?.[1]).toEqual([
      '100',
      '200',
      '20',
      '30',
      4,
      'caught',
      0,
      1,
      '500',
      3,
    ]);
  });

  test('scopes stable event detail reads to the fixture and accepted event set', async () => {
    const query = vi.fn().mockResolvedValue({
      rows: [event('500', 1)],
      rowCount: 1,
      command: 'SELECT',
      oid: 0,
      fields: [],
    });
    const repository = createPublicEventRepository({ query } as unknown as QueryExecutor);

    await expect(repository.findAcceptedFixtureEvent('100', '500')).resolves.toEqual(
      event('500', 1),
    );

    expect(String(query.mock.calls[0]?.[0])).toContain('source_innings.fixture_id = $1::bigint');
    expect(String(query.mock.calls[0]?.[0])).toContain('d.delivery_id = $2::bigint');
    expect(query.mock.calls[0]?.[1]).toEqual(['100', '500', 2]);
import { describe, expect, test, vi } from 'vitest';

import type { QueryExecutor } from '../../src/database';
import { loadFixtureStatisticsSource } from '../../src/modules/statistics/fixture-statistics.repository';

describe('fixture statistics repository', () => {
  test('reads only accepted revisions and preserves event order', async () => {
    const query = vi
      .fn()
      .mockResolvedValueOnce({
        rows: [
          {
            fixtureId: '9',
            ballsPerOver: 6,
            missingFields: [],
            outcome: 'tie',
            winnerCompetitorId: null,
            winnerCompetitorName: null,
            eliminatorCompetitorId: null,
            eliminatorCompetitorName: null,
            outcomeByRuns: null,
            outcomeByWickets: null,
            outcomeMethod: null,
            decidedByBowlOut: false,
            inningsId: '11',
            inningsOrdinal: 0,
            battingCompetitorId: '2',
            battingCompetitorName: 'Team Alpha',
            penaltyPre: null,
            penaltyPost: null,
          },
        ],
        rowCount: 1,
        command: 'SELECT',
        oid: 0,
        fields: [],
      })
      .mockResolvedValueOnce({
        rows: [],
        rowCount: 0,
        command: 'SELECT',
        oid: 0,
        fields: [],
      });
    const executor = { query } as unknown as QueryExecutor;

    const source = await loadFixtureStatisticsSource('9', executor);

    expect(source?.fixtureId).toBe('9');
    expect(source?.innings[0]).toMatchObject({
      battingCompetitorId: '2',
      battingCompetitorName: 'Team Alpha',
    });
    expect(query).toHaveBeenCalledTimes(2);
    expect(query.mock.calls[0]?.[0]).toContain('i.is_super_over = false');

    expect(query.mock.calls[1]?.[0]).toContain('d.innings_id = ANY($1::bigint[])');

    expect(query.mock.calls[1]?.[0]).not.toContain('is_super_over');
    expect(query.mock.calls[0]?.[0]).toContain('winner_team.name AS "winnerCompetitorName"');
    expect(query.mock.calls[0]?.[0]).toContain('batting_team.name AS "battingCompetitorName"');
    expect(query.mock.calls[1]?.[0]).toContain('striker_person.display_name AS "strikerName"');
    expect(query.mock.calls[1]?.[0]).toContain('bowler_person.display_name AS "bowlerName"');
    expect(query.mock.calls[1]?.[1]).toEqual([['11']]);
    expect(query.mock.calls[0]?.[0]).toContain("publication.status = 'accepted'");
    expect(query.mock.calls[1]?.[0]).toContain("source_submission.status = 'accepted'");
    expect(query.mock.calls[1]?.[0]).toContain(
      'DISTINCT ON (d.innings_id, d.over_number, d.position_in_over)',
    );
    expect(query.mock.calls[1]?.[0]).toContain(
      'ORDER BY i.ordinal ASC, d.innings_sequence ASC, d.delivery_id ASC',
    );
  });
});

